                fr_value_box_copy(NULL, dst, src);
                return 0;

+       case FR_TYPE_NULL:
+               fr_value_box_init_null(dst);
+               return 0;
+
        case FR_TYPE_OCTETS:
        case FR_TYPE_STRING:
-       case FR_TYPE_NON_LEAF:
+       case FR_TYPE_INTERNAL:
+       case FR_TYPE_STRUCTURAL:
                fr_assert_fail(NULL);
                return -1; /* shouldn't happen */
        }
